import unittest,re
from tools.kjv_archive import load_register,read
class HebrewsFaithWarningTests(unittest.TestCase):
 def test_faith_warning_and_quoted_self(self):
  prior,_=load_register('0.10-kjv.261');lang,manifest=load_register('0.10-kjv.262')
