  for ref,parts in anchors.items():
   for part in parts:self.assertIn(part,cases[ref.replace(':','-')]['analysis'])
  self.assertIn('body thou for ipl prepare:perf',cases['10-5']['analysis'])
  self.assertIn('thy/will:ev do:inf come:pr kjv_vocative god',cases['10-9']['analysis'])
  self.assertIn('ourone/faith acknowledge:ev',cases['10-23']['analysis'])
  self.assertIn('with which he sanctify:psv:pa',cases['10-29']['analysis'])
  self.assertIn('i in my/chain:pl',cases['10-34']['analysis'])
  self.assertIn('in heaven better',cases['10-34']['analysis'])
  self.assertIn('kjv_substance_faith_hebrews',cases['11-1']['analysis'])
  self.assertIn('kjv_sara_hebrews herself',cases['11-11']['analysis'])
  self.assertIn('both kjv_joseph son:du',cases['11-21']['analysis'])
